    <div class="document">
        <!-- HEADER -->
        <div class="header">
            <h1>The sales effect of “Free App of the Day”<br>on Amazon Appstore: An empirical study</h1>
            <p class="authors">Hong Chen, Kevin Lachaud, Wenqi Zhou</p>

            <!-- HAND IMAGE -->
            <div class="hand-image">
